-- ============================================================================
-- Techsters Academy: DEMO COURSES (editable starter content)
-- ============================================================================
-- Run once in the Supabase SQL editor AFTER master_schema.sql.
-- Safe to re-run: a course is skipped if its slug already exists.
--
-- Creates 5 published courses with modules, lessons, quizzes and assignments.
-- Edit or delete them any time in Instructor studio / Admin → Courses.
-- Video lessons are created WITHOUT a video so you can paste your own link in the lesson editor.
-- ============================================================================

on conflict (slug) do nothing;

do $seed$
declare cid uuid; mid uuid; lid uuid;
begin
  if exists (select 1 from public.courses where slug = $t$web-design-fundamentals$t$) then raise notice 'skipping web-design-fundamentals (already exists)'; return; end if;
  values ($t$web-design-fundamentals$t$, $t$Web Design Fundamentals: HTML & CSS$t$, $t$Build your first responsive web page from scratch and understand how every website is put together.$t$, $t$<p>This beginner course takes you from a blank file to a finished, responsive web page. You will learn how browsers read HTML, how CSS controls layout and colour, and how to make a page that works on phones and laptops.</p><p>It is the first step toward the web development service we deliver to clients every week at Techsters, and it needs nothing more than a laptop and a free code editor.</p>$t$, (select id from public.course_categories where slug = $t$web-development$t$), $t$beginner$t$, 0, null, 'NGN', 'published', true, true, now())
  returning id into cid;
end $seed$;

do $seed$
declare cid uuid; mid uuid; lid uuid;
begin
  if exists (select 1 from public.courses where slug = $t$wordpress-elementor-website$t$) then raise notice 'skipping wordpress-elementor-website (already exists)'; return; end if;
  values ($t$wordpress-elementor-website$t$, $t$Launch a Professional Website with WordPress & Elementor$t$, $t$Plan, build and launch a fast business website without writing code, using the same tools behind many client sites.$t$, $t$<p>Many businesses need a good-looking website quickly, and WordPress with Elementor is a practical way to deliver one. This course walks through the full process: planning pages, installing WordPress, building with Elementor, and preparing the site for launch.</p><p>By the end you will have a complete, mobile-friendly site you can use for your own business or offer to clients.</p>$t$, (select id from public.course_categories where slug = $t$web-development$t$), $t$intermediate$t$, 3000000, 4500000, 'NGN', 'published', false, true, now())
  returning id into cid;
end $seed$;

do $seed$
declare cid uuid; mid uuid; lid uuid;
begin
  if exists (select 1 from public.courses where slug = $t$brand-identity-essentials$t$) then raise notice 'skipping brand-identity-essentials (already exists)'; return; end if;
  values ($t$brand-identity-essentials$t$, $t$Brand Identity Design Essentials$t$, $t$Create a logo, colour palette and visual system that makes a business look credible and memorable.$t$, $t$<p>A brand is more than a logo. It is the way a business looks, sounds and feels everywhere a customer meets it. In this course you will learn the thinking and the practical steps behind a complete visual identity, the same approach we use for client brands.</p><p>You will finish with a mini brand kit: logo concept, colours, typography and usage rules.</p>$t$, (select id from public.course_categories where slug = $t$brand-design$t$), $t$beginner$t$, 2500000, 3500000, 'NGN', 'published', true, true, now())
  returning id into cid;
end $seed$;

do $seed$
declare cid uuid; mid uuid; lid uuid;
begin
  if exists (select 1 from public.courses where slug = $t$social-media-management$t$) then raise notice 'skipping social-media-management (already exists)'; return; end if;
  values ($t$social-media-management$t$, $t$Social Media Management for Business$t$, $t$Plan, create and measure social media content that attracts and converts customers.$t$, $t$<p>Managing social media well takes strategy, consistency and good measurement, not just posting. This course shows you how to set goals, plan content, design simple visuals and report on results for a business or client.</p>$t$, (select id from public.course_categories where slug = $t$social-media$t$), $t$beginner$t$, 2000000, null, 'NGN', 'published', false, true, now())
  returning id into cid;
end $seed$;

do $seed$
declare cid uuid; mid uuid; lid uuid;
begin
  if exists (select 1 from public.courses where slug = $t$ai-automation-small-business$t$) then raise notice 'skipping ai-automation-small-business (already exists)'; return; end if;
  values ($t$ai-automation-small-business$t$, $t$AI & Automation for Small Business$t$, $t$Use AI assistants and no-code automation to save hours every week on writing, admin and customer follow-up.$t$, $t$<p>AI tools and no-code automation can take repetitive work off your plate when used carefully. This course shows you how to write good prompts, choose tasks that are worth automating, and build simple workflows that connect your everyday apps.</p><p>It also covers privacy and accuracy so you use AI responsibly with customer information.</p>$t$, (select id from public.course_categories where slug = $t$ai-productivity$t$), $t$intermediate$t$, 3500000, 5000000, 'NGN', 'published', true, true, now())
  returning id into cid;
end $seed$;

-- Starter articles for the Resources page

-- ----------------------------------------------------------------------------
-- Show YOUR admin account as the instructor of the demo courses.
-- (Admins are also given the Instructor role so the "Taught by" line and the
--  public Instructors page work. Edit your bio under Dashboard → Profile.)
-- Remove this block if you'd rather assign instructors manually in the course editor.
-- ----------------------------------------------------------------------------
select user_id, 'instructor'::public.app_role from public.user_roles where role = 'admin'
on conflict do nothing;

select c.id, r.user_id
from public.courses c cross join public.user_roles r
where r.role = 'admin' and c.slug in ($t$web-design-fundamentals$t$, $t$wordpress-elementor-website$t$, $t$brand-identity-essentials$t$, $t$social-media-management$t$, $t$ai-automation-small-business$t$)
on conflict do nothing;
