  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Structure a page with semantic HTML$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Style it with CSS: colour, type, spacing and layout$t$, 1);
