  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$How the web works$t$, $t$text$t$, 480, true, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>When you type an address into a browser, it asks a server for a page. The server replies with files, and the browser turns those files into what you see. Three languages do most of the work.</p><ul><li><strong>HTML</strong> gives the page its structure and content.</li><li><strong>CSS</strong> controls how that content looks.</li><li><strong>JavaScript</strong> adds behaviour and interactivity.</li></ul><p>In this course we focus on HTML and CSS. Together they are enough to build most business websites you see online.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Set up your workspace$t$, $t$video$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Install VS Code, create a folder called <code>my-first-site</code>, and add a file named <code>index.html</code>. Open it in your browser by double-clicking it.</p>$t$);
  insert into public.course_modules (course_id, title, position) values (cid, $t$HTML and CSS essentials$t$, 1) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Structure a page with HTML$t$, $t$text$t$, 720, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Every HTML page has the same skeleton: a <code>head</code> with information about the page and a <code>body</code> with what visitors see. Inside the body, use elements that describe what the content <em>is</em>.</p><ul><li><code>h1</code> to <code>h3</code> for headings. Use one <code>h1</code> per page.</li><li><code>p</code> for paragraphs, <code>ul</code> and <code>ol</code> for lists.</li><li><code>a</code> for links and <code>img</code> for images (always add an <code>alt</code> description).</li><li><code>header</code>, <code>main</code>, <code>section</code> and <code>footer</code> to organise the page.</li></ul><p>Choosing the right element helps search engines and screen readers understand your page.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Style it with CSS$t$, $t$text$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>CSS works by selecting elements and setting properties. A rule has a selector, then properties and values in curly braces.</p><pre>h1 { color: #0c7c92; font-size: 2.5rem; }</pre><p>Start with these building blocks:</p><ul><li><strong>Colour and type:</strong> <code>color</code>, <code>background</code>, <code>font-family</code>, <code>line-height</code>.</li><li><strong>The box model:</strong> every element has content, <code>padding</code>, <code>border</code> and <code>margin</code>.</li><li><strong>Classes:</strong> reuse styles with <code>.card { ... }</code> and <code>class="card"</code>.</li></ul><p>Keep your colours and font sizes consistent. A small, repeated palette looks more professional than many different shades.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Quiz: HTML and CSS basics$t$, $t$quiz$t$, 300, false, 2) returning id into lid;
  insert into public.quizzes (lesson_id, passing_score, time_limit_minutes, max_attempts, is_required) values (lid, 70, null, null, true);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$Which element should be used for the main heading of a page?$t$, $t$[{"id":"a","text":"<h1>"},{"id":"b","text":"<p>"},{"id":"c","text":"<header>"},{"id":"d","text":"<title>"}]$t$::jsonb, $t$["a"]$t$::jsonb, $t$The h1 element is the top-level heading and should appear once per page.$t$, 1, 0);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$Which CSS property adds space between an element's border and its content?$t$, $t$[{"id":"a","text":"margin"},{"id":"b","text":"padding"},{"id":"c","text":"gap"},{"id":"d","text":"outline"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Padding is inside the border; margin is outside it.$t$, 1, 1);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$multiple$t$, $t$Which of these are semantic HTML elements?$t$, $t$[{"id":"a","text":"<main>"},{"id":"b","text":"<footer>"},{"id":"c","text":"<div>"},{"id":"d","text":"<section>"}]$t$::jsonb, $t$["a","b","d"]$t$::jsonb, $t$main, footer and section describe their purpose. div is a generic container.$t$, 1, 2);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$true_false$t$, $t$The alt attribute on an image helps screen readers and shows if the image fails to load.$t$, $t$[{"id":"true","text":"True"},{"id":"false","text":"False"}]$t$::jsonb, $t$["true"]$t$::jsonb, $t$Alt text describes the image for people who cannot see it and for search engines.$t$, 1, 3);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Layout and launch$t$, 2) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Responsive layout with Flexbox$t$, $t$text$t$, 720, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Flexbox arranges items in a row or column and handles spacing for you. Add <code>display: flex</code> to a container and its children become flex items.</p><ul><li><code>justify-content</code> spaces items along the main axis.</li><li><code>align-items</code> aligns them on the cross axis.</li><li><code>flex-wrap: wrap</code> lets items drop to a new line on small screens.</li><li><code>gap</code> adds even spacing between items.</li></ul><p>Then use a media query such as <code>@media (max-width: 640px)</code> to switch a row of columns into a single stack on phones.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Assignment: build a one-page profile site$t$, $t$assignment$t$, 2700, false, 1) returning id into lid;
  insert into public.assignments (lesson_id, instructions, max_score, allow_resubmission, is_required) values (lid, $t$<p>Build a one-page website about you or a small business you care about.</p><ol><li>Use semantic HTML with one <code>h1</code>, a navigation list, at least two sections and a footer.</li><li>Style it with a consistent colour palette and one font family.</li><li>Make it responsive: it must read well at phone width.</li><li>Zip your project folder, or paste the link if you have published it, and submit.</li></ol><p>You will be graded on structure, consistency of style and responsiveness.</p>$t$, 100, true, true);
