  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Plan a site map and page content before you build$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Install and configure WordPress safely$t$, 1);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Design pages visually with Elementor$t$, 2);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Optimise speed, SEO basics and security before launch$t$, 3);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$Basic computer skills$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$A domain name and hosting (we show you how to choose)$t$, 1);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$Completion of Web Design Fundamentals is helpful but not required$t$, 2);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Plan the website$t$, 0) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Start with the goal, not the theme$t$, $t$text$t$, 540, true, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>The best sites are built around one question: what should a visitor do here? Before opening WordPress, write down the main goal (get enquiries, sell products, book appointments) and who the visitor is.</p><ul><li>List the pages you need. Most small business sites need Home, About, Services, Contact.</li><li>For each page, write the headline and one clear call to action.</li><li>Collect your logo, brand colours and photos in one folder.</li></ul><p>Doing this first saves hours of rework later.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Hosting, domains and installing WordPress$t$, $t$video$t$, 840, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Choose reliable hosting, connect your domain, and use the one-click installer to set up WordPress. Then set your site title, time zone and permalinks (use "Post name").</p>$t$);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Build with Elementor$t$, 1) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Elementor basics: sections, containers and widgets$t$, $t$text$t$, 720, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Elementor lets you build pages visually. Pages are made of containers that hold widgets such as headings, images, buttons and forms.</p><ul><li>Use <strong>containers</strong> for layout: rows, columns and spacing.</li><li>Set <strong>global colours and fonts</strong> once so every page stays consistent.</li><li>Save repeated blocks (like a call-to-action band) as templates.</li></ul><p>Always check the tablet and mobile views as you build, not at the end.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Design a high-converting home page$t$, $t$text$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>A strong home page answers three questions in seconds: what do you do, who is it for, and what should I do next.</p><ol><li>A clear headline and sub-headline above the fold.</li><li>One primary button, such as "Book a consultation".</li><li>Your services in three or four short blocks.</li><li>Proof: client logos, short testimonials or results.</li><li>A final call to action and full contact details in the footer.</li></ol>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Quiz: WordPress and Elementor$t$, $t$quiz$t$, 300, false, 2) returning id into lid;
  insert into public.quizzes (lesson_id, passing_score, time_limit_minutes, max_attempts, is_required) values (lid, 70, null, null, true);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$What should you do before building any pages?$t$, $t$[{"id":"a","text":"Pick a theme"},{"id":"b","text":"Define the site goal and list the pages needed"},{"id":"c","text":"Install every plugin"},{"id":"d","text":"Buy ads"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Planning the goal and structure first prevents rework.$t$, 1, 0);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$Where should you set brand colours so they apply everywhere?$t$, $t$[{"id":"a","text":"On each widget"},{"id":"b","text":"In global site settings"},{"id":"c","text":"In the hosting panel"},{"id":"d","text":"In the media library"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Global colours and fonts keep the whole site consistent.$t$, 1, 1);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$true_false$t$, $t$You only need to check the mobile view at the end of the project.$t$, $t$[{"id":"true","text":"True"},{"id":"false","text":"False"}]$t$::jsonb, $t$["false"]$t$::jsonb, $t$Check tablet and mobile views as you build.$t$, 1, 2);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$multiple$t$, $t$Which belong on a strong home page?$t$, $t$[{"id":"a","text":"A clear headline"},{"id":"b","text":"A primary call-to-action button"},{"id":"c","text":"Social proof"},{"id":"d","text":"Ten different fonts"}]$t$::jsonb, $t$["a","b","c"]$t$::jsonb, $t$Clarity, one main action and proof convert visitors.$t$, 1, 3);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Optimise and launch$t$, 2) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Speed, SEO and security checklist$t$, $t$text$t$, 600, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Before launch, go through this checklist:</p><ul><li>Compress images and use modern formats such as WebP.</li><li>Add a unique title and meta description to every page.</li><li>Install an SSL certificate so the site loads over https.</li><li>Keep WordPress, themes and plugins updated and remove unused ones.</li><li>Set up automatic backups and a contact-form spam filter.</li></ul><p>Test the contact form, then test the site on a real phone.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Assignment: launch-ready site plan and home page$t$, $t$assignment$t$, 3600, false, 1) returning id into lid;
  insert into public.assignments (lesson_id, instructions, max_score, allow_resubmission, is_required) values (lid, $t$<p>Prepare a launch-ready home page for a real or imaginary business.</p><ol><li>Submit a short site map listing every page and its main call to action.</li><li>Share a link to your home page (staging is fine) or screenshots of desktop and mobile views.</li><li>Include the launch checklist with each item marked done or not done.</li></ol><p>Graded on clarity of structure, design consistency and completeness of the checklist.</p>$t$, 100, true, true);
  insert into public.courses (slug, title, subtitle, description, category_id, level, price_minor, compare_at_minor, currency, status, is_featured, certificate_enabled, published_at)
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Define brand personality and positioning$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Design a simple, versatile logo$t$, 1);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Build a colour palette and type system with purpose$t$, 2);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Package everything into a clear brand guideline$t$, 3);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$A computer with any design tool (Canva, Figma or Illustrator)$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$No prior design experience needed$t$, 1);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Brand foundations$t$, 0) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$What a brand really is$t$, $t$text$t$, 480, true, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>A brand is the impression people carry about a business. A logo is one small part of it. Strong brands are <strong>clear</strong>, <strong>consistent</strong> and <strong>distinct</strong>.</p><ul><li><strong>Clear:</strong> people understand what you offer and who it is for.</li><li><strong>Consistent:</strong> the same colours, type and tone everywhere.</li><li><strong>Distinct:</strong> you look different from competitors in a meaningful way.</li></ul><p>Design decisions should follow from these ideas, not from personal taste.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Research and positioning$t$, $t$video$t$, 780, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Interview the owner, list three direct competitors, and write a one-sentence positioning statement: "We help [audience] to [outcome] through [approach]."</p>$t$);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Designing the identity$t$, 1) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Logo design principles$t$, $t$text$t$, 720, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>A good logo is simple enough to recognise at small sizes and strong enough to work in one colour.</p><ul><li>Sketch many ideas on paper before opening software.</li><li>Test it small (a social media avatar) and large (a banner).</li><li>Design a horizontal, stacked and icon-only version.</li><li>Check it in black and white.</li></ul><p>Avoid trends that will date quickly and avoid clip art, which can lead to copyright problems.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Colour and typography$t$, $t$text$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Choose one primary colour, one or two supporting colours and a set of neutrals. Colours carry meaning, but context matters, so test them against your audience and competitors.</p><ul><li>Check text contrast so everything stays readable (aim for WCAG AA).</li><li>Use at most two typefaces: one for headings, one for body text.</li><li>Define sizes for headings, subheadings and body text.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Quiz: brand identity$t$, $t$quiz$t$, 300, false, 2) returning id into lid;
  insert into public.quizzes (lesson_id, passing_score, time_limit_minutes, max_attempts, is_required) values (lid, 70, null, null, true);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$Which best describes a brand?$t$, $t$[{"id":"a","text":"A logo"},{"id":"b","text":"The overall impression people have of a business"},{"id":"c","text":"A colour palette"},{"id":"d","text":"A slogan"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Logos, colours and slogans are parts of a brand, not the whole.$t$, 1, 0);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$multiple$t$, $t$A good logo should work...$t$, $t$[{"id":"a","text":"At very small sizes"},{"id":"b","text":"In one colour"},{"id":"c","text":"Only on white backgrounds"},{"id":"d","text":"In horizontal and stacked layouts"}]$t$::jsonb, $t$["a","b","d"]$t$::jsonb, $t$Versatility is a core test of a logo.$t$, 1, 1);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$true_false$t$, $t$A brand should use as many typefaces as possible to look creative.$t$, $t$[{"id":"true","text":"True"},{"id":"false","text":"False"}]$t$::jsonb, $t$["false"]$t$::jsonb, $t$Two typefaces at most keeps the identity consistent.$t$, 1, 2);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$What is the first step before designing a logo?$t$, $t$[{"id":"a","text":"Choose fonts"},{"id":"b","text":"Research the business, audience and competitors"},{"id":"c","text":"Pick a colour"},{"id":"d","text":"Buy a template"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Research informs every design decision.$t$, 1, 3);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Deliver the brand$t$, 2) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Write brand guidelines$t$, $t$text$t$, 600, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Brand guidelines make sure anyone can use the identity correctly. Keep them short and visual.</p><ul><li>Logo versions and minimum sizes.</li><li>Clear space and what not to do.</li><li>Colour codes (HEX and RGB).</li><li>Typography and sample layouts.</li><li>Tone of voice in two or three sentences.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Assignment: your mini brand kit$t$, $t$assignment$t$, 5400, false, 1) returning id into lid;
  insert into public.assignments (lesson_id, instructions, max_score, allow_resubmission, is_required) values (lid, $t$<p>Create a mini brand kit for a real or imaginary business.</p><ol><li>A one-sentence positioning statement.</li><li>A logo in at least two layouts, shown in colour and in black and white.</li><li>A colour palette with codes and a type pairing.</li><li>Two applications, for example a social media post and a business card.</li></ol><p>Upload a PDF or link to your design file. Graded on clarity, consistency and appropriateness for the audience.</p>$t$, 100, true, true);
