  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Goals, audience and platforms$t$, $t$text$t$, 540, true, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Start by deciding what social media is for. Common goals are awareness, enquiries, sales and customer support. Pick one main goal for each quarter.</p><ul><li>Describe your ideal customer: age, location, interests, problems.</li><li>Choose two platforms where they already spend time. Do those well rather than posting everywhere.</li><li>Decide what success looks like, for example 20 enquiries a month.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Content pillars and tone of voice$t$, $t$video$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Define three to four content pillars, such as education, behind the scenes, proof and offers. They keep posting varied but focused.</p>$t$);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Create and schedule$t$, 1) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Plan a content calendar$t$, $t$text$t$, 720, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>A content calendar turns ideas into a routine. Plan a month at a time.</p><ol><li>List key dates: launches, holidays and events.</li><li>Assign each post a pillar, format and goal.</li><li>Write captions with a hook in the first line and a clear call to action.</li><li>Schedule posts with a free scheduler where possible.</li></ol>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Design posts that stop the scroll$t$, $t$text$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Good social visuals are simple. Use your brand colours and fonts, keep text large and short, and leave space around elements.</p><ul><li>One idea per post.</li><li>High-contrast text that is readable on a phone.</li><li>Use real photos of your products and team where you can.</li><li>Add captions to videos, since many people watch without sound.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Quiz: social media strategy$t$, $t$quiz$t$, 300, false, 2) returning id into lid;
  insert into public.quizzes (lesson_id, passing_score, time_limit_minutes, max_attempts, is_required) values (lid, 70, null, null, true);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$What should you decide before choosing platforms?$t$, $t$[{"id":"a","text":"The hashtags"},{"id":"b","text":"The goal and the audience"},{"id":"c","text":"The posting time"},{"id":"d","text":"The logo"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Goals and audience determine where to be active.$t$, 1, 0);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$true_false$t$, $t$It is best to be active on every platform from day one.$t$, $t$[{"id":"true","text":"True"},{"id":"false","text":"False"}]$t$::jsonb, $t$["false"]$t$::jsonb, $t$Focus on two platforms and do them well.$t$, 1, 1);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$multiple$t$, $t$Which are good practices for post visuals?$t$, $t$[{"id":"a","text":"One idea per post"},{"id":"b","text":"Large readable text"},{"id":"c","text":"Cluttered layouts"},{"id":"d","text":"Brand colours and fonts"}]$t$::jsonb, $t$["a","b","d"]$t$::jsonb, $t$Simple, branded, readable visuals perform best.$t$, 1, 2);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$What is a content pillar?$t$, $t$[{"id":"a","text":"A paid ad"},{"id":"b","text":"A recurring theme your content covers"},{"id":"c","text":"A follower count"},{"id":"d","text":"A scheduling tool"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$Pillars keep content varied but focused.$t$, 1, 3);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Measure and improve$t$, 2) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Metrics that matter$t$, $t$text$t$, 600, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Vanity metrics like likes feel good but do not always show business results. Track:</p><ul><li><strong>Reach and impressions:</strong> how many people saw your content.</li><li><strong>Engagement rate:</strong> interactions divided by reach.</li><li><strong>Clicks and enquiries:</strong> actions that lead to business.</li><li><strong>Follower growth:</strong> useful when combined with the above.</li></ul><p>Review monthly, keep what works and stop what does not.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Assignment: one-month content plan$t$, $t$assignment$t$, 3600, false, 1) returning id into lid;
  insert into public.assignments (lesson_id, instructions, max_score, allow_resubmission, is_required) values (lid, $t$<p>Create a one-month content plan for a real or imaginary business.</p><ol><li>State the goal and the target audience.</li><li>Define three content pillars.</li><li>Provide a calendar with at least 12 posts, each with a caption and a call to action.</li><li>Design two of the posts and attach them.</li></ol><p>Upload a document or share a link.</p>$t$, 100, true, true);
  insert into public.courses (slug, title, subtitle, description, category_id, level, price_minor, compare_at_minor, currency, status, is_featured, certificate_enabled, published_at)
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Write clear prompts that produce useful results$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Identify tasks worth automating in your business$t$, 1);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Build a simple no-code workflow between apps$t$, 2);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'outcome', $t$Use AI safely: accuracy, privacy and review$t$, 3);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$Comfort using web apps and email$t$, 0);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$A free account with an AI assistant of your choice$t$, 1);
  insert into public.course_requirements (course_id, kind, body, position) values (cid, 'requirement', $t$No programming needed$t$, 2);
  insert into public.course_modules (course_id, title, position) values (cid, $t$AI basics for work$t$, 0) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$What AI assistants can and cannot do$t$, $t$text$t$, 540, true, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>AI assistants are very good at drafting, summarising, brainstorming and reformatting. They can also be confidently wrong. Treat their output as a first draft that you review.</p><ul><li><strong>Good for:</strong> first drafts, email replies, summaries, ideas, tidying data.</li><li><strong>Be careful with:</strong> facts, figures, legal or medical advice, and anything customer-facing without review.</li><li><strong>Never paste:</strong> passwords, payment details or private customer data into tools you have not approved.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Prompting that works$t$, $t$video$t$, 840, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Give the assistant a role, the task, the context, the format you want and any constraints. Then refine with follow-up instructions.</p>$t$);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Automate your workflow$t$, 1) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Find tasks worth automating$t$, $t$text$t$, 660, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Automate tasks that are repetitive, rule-based and frequent. A quick test: if you do it more than weekly and it follows the same steps, it is a candidate.</p><ul><li>New enquiry arrives: send a confirmation and add it to a sheet.</li><li>Invoice paid: notify the team and update your records.</li><li>New blog post: share a draft caption to social media for approval.</li></ul><p>Start with one small workflow and make it reliable before adding more.</p>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Build a trigger-and-action workflow$t$, $t$text$t$, 720, false, 1) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>No-code tools connect apps using triggers (something happens) and actions (do something). Map it on paper first.</p><ol><li>Choose the trigger, for example a form submission.</li><li>Add actions: save to a spreadsheet, send an email, create a task.</li><li>Add a human check for anything customer-facing.</li><li>Test with sample data and turn it on.</li></ol>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Quiz: AI and automation$t$, $t$quiz$t$, 300, false, 2) returning id into lid;
  insert into public.quizzes (lesson_id, passing_score, time_limit_minutes, max_attempts, is_required) values (lid, 70, null, null, true);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$How should AI output be treated?$t$, $t$[{"id":"a","text":"As always correct"},{"id":"b","text":"As a first draft to review"},{"id":"c","text":"As legal advice"},{"id":"d","text":"As private"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$AI can be confidently wrong, so always review.$t$, 1, 0);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$true_false$t$, $t$It is fine to paste customer payment details into any AI tool.$t$, $t$[{"id":"true","text":"True"},{"id":"false","text":"False"}]$t$::jsonb, $t$["false"]$t$::jsonb, $t$Never share sensitive data with tools you have not approved.$t$, 1, 1);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$multiple$t$, $t$Which tasks are good candidates for automation?$t$, $t$[{"id":"a","text":"Repetitive tasks"},{"id":"b","text":"Rule-based tasks"},{"id":"c","text":"One-off creative decisions"},{"id":"d","text":"Frequent tasks"}]$t$::jsonb, $t$["a","b","d"]$t$::jsonb, $t$Repetitive, rule-based, frequent tasks gain the most.$t$, 1, 2);
  insert into public.quiz_questions (lesson_id, type, prompt, options, correct, explanation, points, position) values (lid, $t$single$t$, $t$What are the two parts of a simple automation?$t$, $t$[{"id":"a","text":"Title and body"},{"id":"b","text":"Trigger and action"},{"id":"c","text":"Input and font"},{"id":"d","text":"Plan and price"}]$t$::jsonb, $t$["b"]$t$::jsonb, $t$A trigger starts the workflow; actions carry out the steps.$t$, 1, 3);
  insert into public.course_modules (course_id, title, position) values (cid, $t$Use AI responsibly$t$, 2) returning id into mid;
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Accuracy, privacy and review$t$, $t$text$t$, 600, false, 0) returning id into lid;
  insert into public.lesson_content (lesson_id, body_html) values (lid, $t$<p>Build review into every workflow.</p><ul><li>Check facts and figures against a trusted source.</li><li>Anonymise data before sharing it with a tool.</li><li>Disclose AI-assisted content where your audience would expect it.</li><li>Keep a person responsible for the final result.</li></ul>$t$);
  insert into public.lessons (module_id, course_id, title, type, duration_seconds, is_preview, position) values (mid, cid, $t$Assignment: design an automation for your business$t$, $t$assignment$t$, 3600, false, 1) returning id into lid;
  insert into public.assignments (lesson_id, instructions, max_score, allow_resubmission, is_required) values (lid, $t$<p>Design one workflow that would save you time.</p><ol><li>Describe the task, how often it happens and how long it takes now.</li><li>Draw or list the trigger and each action.</li><li>Write the prompt you would use for any AI step.</li><li>Explain how a person reviews the result and how you protect private data.</li></ol><p>Submit a document or share a link.</p>$t$, 100, true, true);
insert into public.blog_posts (slug, title, excerpt, body_html, is_published, published_at) values ($t$how-to-choose-your-first-digital-skill$t$, $t$How to choose your first digital skill$t$, $t$Not sure where to begin? Four questions to help you pick a skill that fits your goals.$t$, $t$<p>With so many options, choosing a first digital skill can feel overwhelming. Start with the outcome you want, then work backwards.</p><h2>1. What do you want to achieve?</h2><p>A new job, a side income, or a better online presence for your business each point to different skills.</p><h2>2. What do you already enjoy?</h2><p>If you like visuals, look at brand or graphic design. If you like structure and logic, try web development. If you like people and storytelling, social media may suit you.</p><h2>3. Can you practise every week?</h2><p>Consistency beats intensity. Pick something you can practise for a few hours each week.</p><h2>4. What can you build to prove it?</h2><p>Choose a skill where you can create real work to show others, such as a website, a brand kit or a content plan.</p>$t$, true, now()) on conflict (slug) do nothing;
insert into public.blog_posts (slug, title, excerpt, body_html, is_published, published_at) values ($t$website-launch-checklist-for-small-businesses$t$, $t$A website launch checklist for small businesses$t$, $t$Seven things to check before you tell the world your new website is live.$t$, $t$<p>Before launch day, walk through this checklist.</p><ol><li><strong>Content:</strong> proofread every page and check names, prices and phone numbers.</li><li><strong>Mobile:</strong> open the site on a real phone and tap every button.</li><li><strong>Forms:</strong> submit each form and confirm you receive the message.</li><li><strong>Speed:</strong> compress images and remove anything unused.</li><li><strong>SEO basics:</strong> unique page titles and descriptions.</li><li><strong>Security:</strong> https enabled, software updated, backups on.</li><li><strong>Measurement:</strong> analytics installed so you can learn from visitors.</li></ol><p>Then launch, and plan to review the site monthly.</p>$t$, true, now()) on conflict (slug) do nothing;
